import java.nio.file.*;import java.util.*;import java.io.*;import java.security.*;
public class SpotProbe {
 static Path dir;static Map<Integer,AnimBase>bases=new HashMap<>();static AnimBase base(int id)throws Exception{AnimBase b=bases.get(id);if(b==null){b=new AnimBase(id,read("base_"+id+".bin"));bases.put(id,b);}return b;}
 static byte[]read(String file)throws Exception{return Files.readAllBytes(dir.resolve(file));}
 static Object field(Object value,String key)throws Exception{var f=value.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(value);}
 static String pairs(SpotAnimType d,String a,String b)throws Exception{short[]x=(short[])field(d,a),y=(short[])field(d,b);List<String>out=new ArrayList<>();if(x!=null)for(int i=0;i<x.length;i++)out.add("["+(x[i]&65535)+","+(y[i]&65535)+"]");return out.toString();}
 static String metadata(SpotAnimType d)throws Exception{return "{\"model\":"+field(d,"modelId")+",\"sequence\":"+d.seqId+",\"resize\":["+field(d,"resizeXZ")+","+field(d,"resizeY")+"],\"angle\":"+field(d,"angle")+",\"ambient\":"+field(d,"ambient")+",\"contrast\":"+field(d,"contrast")+",\"align_to_terrain\":"+d.alignToTerrain+",\"recolor\":"+pairs(d,"recol_s","recol_d")+",\"retexture\":"+pairs(d,"retex_s","retex_d")+"}";}
 static void frame(SeqType seq,int index,String file,int base)throws Exception{if(index<0)return;int id=seq.frames[index],group=id>>>16,slot=id&65535;AnimFrame f=new AnimFrame(read(file),base(base));AnimFrameset old=SeqTypeList.groups.get(group);AnimFrame[]a=old==null?new AnimFrame[slot+1]:Arrays.copyOf(old.frames,Math.max(old.frames.length,slot+1));a[slot]=f;SeqTypeList.groups.put(group,new AnimFrameset(a));}
 static String geometry(GlModel g)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeInt(g.vertexCount);for(int i=0;i<g.vertexCount;i++){out.writeInt(g.vertexX[i]);out.writeInt(g.vertexY[i]);out.writeInt(g.vertexZ[i]);}int max=-1;for(short s:g.triangleSources)max=Math.max(max,s&65535);int[]lookup=new int[max+1];Arrays.fill(lookup,-1);for(int i=0;i<g.triangleCount;i++)lookup[g.triangleSources[i]&65535]=i;for(int i:lookup)if(i>=0){for(int v:new int[]{g.triangleVertexA[i]&65535,g.triangleVertexB[i]&65535,g.triangleVertexC[i]&65535}){out.writeInt(g.normalX[v]);out.writeInt(g.normalY[v]);out.writeInt(g.normalZ[v]);out.writeInt(g.normalMagnitude[v]);}out.writeShort(g.triangleColors[i]);out.writeByte(g.triangleAlpha[i]);}return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()));}
 public static void main(String[]args)throws Exception{dir=Path.of(args[0]);Rasteriser.textureProvider=new VisualMaterials(read("materials.bin"));SpotAnimTypeList.modelsArchive=new Js5(dir);BufferedReader reader=new BufferedReader(new InputStreamReader(System.in));String line;while((line=reader.readLine())!=null){String[]p=line.split(";");switch(p[0]){
 case"D":{Buffer b=new Buffer(HexFormat.of().parseHex(p[1]));SpotAnimType d=new SpotAnimType();d.decode(b);System.out.println("{\"position\":"+b.offset+",\"definition\":"+metadata(d)+"}");break;}
 case"S":{SeqType s=new SeqType();s.decode(new Buffer(read(p[1])));List<String>rows=new ArrayList<>();if(s.soundeffect!=null)for(int i=0;i<s.soundeffect.length;i++)if(s.soundeffect[i]!=null)rows.add("["+i+","+Arrays.toString(s.soundeffect[i])+"]");System.out.println(rows);break;}
 case"P":{int id=Integer.parseInt(p[1]);SpotAnimType d=new SpotAnimType();d.id=id;d.decode(new Buffer(read(p[2])));SpotAnimTypeList.types.put(id,d);SpotAnimTypeList.models.values.clear();SeqType s=new SeqType();s.decode(new Buffer(read(p[3])));SeqTypeList.types.put(d.seqId,s);SeqTypeList.groups.clear();bases.clear();int a=Integer.parseInt(p[4]),b=Integer.parseInt(p[5]);frame(s,a,p[6],Integer.parseInt(p[7]));frame(s,b,p[8],Integer.parseInt(p[9]));SeqType.applyTweening=Boolean.parseBoolean(p[11]);GlModel g;
 if(a<0){g=d.constructModel(-1,-1,1);g.translate(0,-Integer.parseInt(p[13]),0);if(d.alignToTerrain){g.rotateX(Integer.parseInt(p[14]));g.rotateZ(Integer.parseInt(p[15]));g.translate(0,Integer.parseInt(p[16]),0);}}
 else{SpotEntity.terrainPitchAngle=Integer.parseInt(p[14]);SpotEntity.terrainRollAngle=Integer.parseInt(p[15]);SpotEntity.terrainYOffset=Integer.parseInt(p[16]);SpotAttachment actor=new SpotAttachment();actor.spotAnimId=id;actor.spotAnimFrame=a;actor.spotAnimNextFrame=b;actor.spotAnimDelayClock=Integer.parseInt(p[10])+1;actor.spotAnimY=Integer.parseInt(p[13]);g=p[12].equals("Npc")?actor.attachNpc():actor.attachPlayer();}
 System.out.println(geometry(g));break;}
 case"T":{SpotAnimType d=new SpotAnimType();d.id=777;d.decode(new Buffer(HexFormat.of().parseHex(p[1])));GlModel m=new GlModel();m.bounds=new GlBoundingBox();m.vertexBuffer=new GlBuffer();int[]v=Arrays.stream(p[2].split(",")).mapToInt(Integer::parseInt).toArray();m.vertexCount=v.length/3;m.vertexX=new int[m.vertexCount];m.vertexY=new int[m.vertexCount];m.vertexZ=new int[m.vertexCount];for(int i=0;i<m.vertexCount;i++){m.vertexX[i]=v[i*3];m.vertexY[i]=v[i*3+1];m.vertexZ[i]=v[i*3+2];}SpotAnimTypeList.models.values.clear();SpotAnimTypeList.models.put(m,777);GlModel g=d.constructModel(-1,-1,1);List<String>out=new ArrayList<>();for(int i=0;i<g.vertexCount;i++)out.add(Arrays.toString(new int[]{g.vertexX[i],g.vertexY[i],g.vertexZ[i]}));System.out.println(out);break;}
 case"A":{int[]a=Arrays.stream(p[1].split(",")).mapToInt(Integer::parseInt).toArray();SpotGround.calls.clear();SpotGround.index=0;SpotGround.plane=2;SpotGround.heights=Arrays.copyOfRange(a,6,10);SpotEntity e=new SpotEntity();e.bas.terrainAlignWidth=a[0];e.bas.terrainAlignDepth=a[1];e.xFine=a[3];e.yFine=a[4];e.tileHeight=a[5];GlModel g=new GlModel();g.bounds=new GlBoundingBox();g.vertexBuffer=new GlBuffer();e.alignToTerrain(g,a[2]);List<String>calls=new ArrayList<>();for(int[]c:SpotGround.calls)calls.add(Arrays.toString(c));System.out.println("{\"alignment\":{\"pitch\":"+SpotEntity.terrainPitchAngle+",\"roll\":"+SpotEntity.terrainRollAngle+",\"offset\":"+SpotEntity.terrainYOffset+"},\"calls\":"+calls+"}");break;}
 default:throw new AssertionError(p[0]);}}}
}
